template exportGaugeModule*(T: typedesc) =
  ## Defines `gauge_module`'s exported symbols over the handlers of `T`.
  proc gaugeModuleKitCreate(init: ModuleInit): Result[pointer, InvocationFailure] {.nimcall, gcsafe, raises: [].} =
    ?kitNoConfiguration(init)
    let r = initModule(T, init)
    if r.isErr:
      return err(r.error)
    let instance = r.get
    if instance.isNil:
      return err(moduleError("initModule returned nil"))
    GC_ref(instance)
    ok(cast[pointer](instance))

  proc gaugeModuleKitDispose(p: pointer) {.nimcall, gcsafe, raises: [].} =
    let instance {.cursor.} = cast[T](p)
    when compiles(destroyModule(instance)):
      destroyModule(instance)
    GC_unref(instance)

  proc gaugeModuleKitName(): cstring {.exportc: "logos_gauge_module_MODULE_name", dynlib, cdecl, gcsafe, raises: [].} =
    system.cstring(moduleName)

  proc gaugeModuleKitInit(input: ptr LogosModuleInitInput, outContext: ptr ptr LogosModuleContext): LogosResult {.exportc: "logos_gauge_module_MODULE_init", dynlib, cdecl, gcsafe, raises: [].} =
    kitEnter()
    kitInit(input, outContext, declaresEvents, gaugeModuleKitCreate)

  proc gaugeModuleKitDestroy(module: ptr LogosModuleContext) {.exportc: "logos_gauge_module_MODULE_destroy", dynlib, cdecl, gcsafe, raises: [].} =
    kitEnter()
    kitDestroy(module, gaugeModuleKitDispose)

  proc gaugeModuleKitRoute(p: pointer, bare: string, params: openArray[byte]): Result[seq[byte], InvocationFailure] {.nimcall, gcsafe, raises: [].} =
    let instance {.cursor.} = cast[T](p)
    routeGaugeModule(instance, bare, params)

  proc gaugeModuleKitCallSurface(outLen: ptr csize_t): ptr uint8 {.exportc: "logos_gauge_module_MODULE_call_surface", dynlib, cdecl, gcsafe, raises: [].} =
    if outLen != nil:
      outLen[] = csize_t(callSurfaceData.len)
    addr callSurfaceData[0]

  proc gaugeModuleKitFree(module: ptr LogosModuleContext, p: pointer) {.exportc: "logos_gauge_module_MODULE_free", dynlib, cdecl, gcsafe, raises: [].} =
    kitEnter()
    kitFree(module, p)

  proc gaugeModuleKitDispatch(module: ptr LogosModuleContext, methodName: cstring, paramsCbor: ptr UncheckedArray[uint8], paramsLen: csize_t, outResponseCbor: ptr ptr UncheckedArray[uint8], outResponseLen: ptr csize_t): LogosResult {.exportc: "logos_gauge_module_MODULE_dispatch", dynlib, cdecl, gcsafe, raises: [].} =
    kitEnter()
    kitDispatch(module, methodName, paramsCbor, paramsLen, outResponseCbor, outResponseLen, gaugeModuleKitRoute)

  proc gaugeModuleStaticSymbols*(): seq[(string, pointer)] =
    ## [SPEC RUNTIME §13.3] `gauge_module`'s symbol table for static registration.
    @[
      ("logos_gauge_module_MODULE_name", cast[pointer](gaugeModuleKitName)),
      ("logos_gauge_module_MODULE_init", cast[pointer](gaugeModuleKitInit)),
      ("logos_gauge_module_MODULE_destroy", cast[pointer](gaugeModuleKitDestroy)),
      ("logos_gauge_module_MODULE_call_surface", cast[pointer](gaugeModuleKitCallSurface)),
      ("logos_gauge_module_MODULE_free", cast[pointer](gaugeModuleKitFree)),
      ("logos_gauge_module_MODULE_dispatch", cast[pointer](gaugeModuleKitDispatch)),
    ]
